<?php
session_start();require '../../config/db.php';if(!isset($_SESSION['admin_id'])){header('Location: ../../auth/login-admin.php');exit;}function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function badgeStatus($s){$c='st-'.str_replace(' ','-',strtolower((string)$s));return '<span class="hd-badge '.h($c).'">'.h(ucfirst((string)$s)).'</span>';}$cliente_id=(int)($_GET['id']??0);if($cliente_id<=0){$_SESSION['error_msg']='Cliente não especificado.';header('Location: lista-clientes.php');exit;}$stmt=$pdo->prepare('SELECT * FROM clientes WHERE id=?');$stmt->execute([$cliente_id]);$cliente=$stmt->fetch(PDO::FETCH_ASSOC);if(!$cliente){$_SESSION['error_msg']='Cliente não encontrado.';header('Location: lista-clientes.php');exit;}$stmt=$pdo->prepare('SELECT * FROM solicitacoes WHERE cliente_id=? ORDER BY data DESC');$stmt->execute([$cliente_id]);$solicitacoes=$stmt->fetchAll(PDO::FETCH_ASSOC);?>
<!DOCTYPE html><html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Chamados de <?=h($cliente['nome'])?></title><link rel="stylesheet" href="../../assets/css/helpdesk-pro.css"></head><body><div class="hd-page"><header class="hd-topbar"><div class="hd-container hd-topbar-inner"><div class="hd-brand"><div class="hd-client-logo-box"><?php if(!empty($cliente['logo'])):?><img src="../../uploads/clientes/logos/<?=h(basename($cliente['logo']))?>" alt="Logo"><?php else:?>📋<?php endif;?></div><div><h1>Chamados do cliente</h1><p><?=h($cliente['nome'])?> • <?=h($cliente['email'])?></p></div></div><div class="hd-user"><a class="hd-chip" href="dashboard.php">Dashboard</a><a class="hd-chip" href="editar-cliente.php?id=<?=$cliente_id?>">Editar cliente</a><a class="hd-chip" href="lista-clientes.php">Clientes</a></div></div></header><main class="hd-main"><div class="hd-container"><section class="hd-card hd-card-pad"><div class="hd-section-head"><div><h2>Histórico de chamados</h2><p><?=count($solicitacoes)?> solicitação(ões) registradas.</p></div><button class="hd-btn hd-btn-outline" onclick="imprimirRelatorio()">🖨️ Imprimir</button></div><div class="hd-table-wrap"><table class="hd-table"><thead><tr><th>Chamado</th><th>Status</th><th>Prioridade</th><th>Data</th><th>Valor</th><th>Ações</th></tr></thead><tbody><?php foreach($solicitacoes as $s):?><tr><td><div class="hd-ticket-title"><?=h($s['titulo']?:mb_substr($s['descricao'],0,90))?></div><div class="hd-ticket-meta"><?=h($s['protocolo']?:'#'.$s['id'])?> • <?=h($s['categoria']?:'Suporte técnico')?></div><div class="hd-ticket-meta"><?=h(mb_strimwidth($s['descricao'],0,160,'...'))?></div></td><td><?=badgeStatus($s['status'])?></td><td><span class="hd-badge pr-<?=h($s['prioridade']?:'media')?>"><?=h(ucfirst($s['prioridade']?:'media'))?></span></td><td><span class="hd-ticket-meta"><?=date('d/m/Y H:i',strtotime($s['data']))?></span></td><td><strong>R$ <?=number_format((float)($s['preco']??0),2,',','.')?></strong></td><td><details><summary class="hd-btn hd-btn-outline">Gerenciar</summary><div style="min-width:280px;margin-top:10px;display:grid;gap:10px"><form method="POST" action="../../controllers/atualizar-status.php" class="hd-field"><input type="hidden" name="solicitacao_id" value="<?=(int)$s['id']?>"><select class="hd-select" name="novo_status"><?php foreach(['pendente','em andamento','finalizado','nao resolvido','cancelado'] as $st):?><option value="<?=h($st)?>" <?=$s['status']===$st?'selected':''?>><?=h(ucfirst($st))?></option><?php endforeach;?></select><button class="hd-btn hd-btn-primary" type="submit">Atualizar status</button></form></div></details></td></tr><?php endforeach;?><?php if(!$solicitacoes):?><tr><td colspan="6"><div class="hd-empty">📭<strong>Nenhum chamado para este cliente</strong></div></td></tr><?php endif;?></tbody></table></div></section></div></main></div><script src="../../assets/js/helpdesk-pro.js"></script></body></html>